blocks.code:
db.orders.aggregate([
  { $match: { status: 'paid' } },
  { $unwind: '$lines' },
  { $group: {
      _id: { $dateToString: { format: '%Y-%m', date: '$placedAt' } },
      revenue: { $sum: { $multiply: ['$lines.qty', '$lines.price'] } }
  } },
  { $sort: { _id: 1 } },
  { $project: { _id: 0, month: '$_id', revenue: { $round: ['$revenue', 2] } } }
])
